INSERT INTO public.translations (locale, key, value) VALUES
  ('en', 'onboardingChapterWelcome', 'Welcome to MatchMe'),
  ('en', 'onboardingChapterHome', 'Your home screen'),
  ('en', 'onboardingChapterNearby', 'Discover people nearby'),
  ('en', 'onboardingChapterMatches', 'Your matches'),
  ('en', 'onboardingChapterChats', 'Chat safely'),
  ('en', 'onboardingChapterEvents', 'Join events'),
  ('en', 'onboardingChapterProfile', 'Your profile'),
  ('en', 'onboardingChapterSettings', 'Matching settings'),
  ('en', 'onboardingChapterFinish', 'You''re all set!'),
  ('en', 'onboardingBeatWelcome1', 'Welcome to MatchMe… MatchMe helps you find people nearby who share your interests and intentions. Build a profile, set your preferences, and the app quietly finds compatible people around you. Tap Next to move ahead, or Skip to leave the tour at any time.'),
  ('en', 'onboardingBeatWelcome2', 'Here is how it works… You set your interests and who you are looking for. MatchMe checks who is nearby, who shares your intentions, and whether your preferences align. When both people want the same connection, a match is created. Verifying your profile with a live selfie earns you a trusted badge.'),
  ('en', 'onboardingBeatHome1', 'This is your home screen, your daily dashboard… Everything on MatchMe is reachable from here with one tap.'),
  ('en', 'onboardingBeatHome2', 'The cards up top show how many people are nearby right now, who is online, and your subscription tier. Tap a card to open it.'),
  ('en', 'onboardingBeatHome3', 'Below, your most recent matches and chats are waiting, so you can pick up right where you left off.'),
  ('en', 'onboardingBeatHome4', 'Use these filter chips to focus on what you are here for… friends, dating, or any other intent you selected in your profile.'),
  ('en', 'onboardingBeatHome5', 'Behind the scenes, MatchMe is continuously comparing your preferences with other members nearby… Background matching keeps searching even when you are not actively using the app, so fresh matches appear in real time.'),
  ('en', 'onboardingBeatHome6', 'What creates a match depends on your settings… Your search radius, age range, gender preferences, shared interests, and lifestyle filters all determine who appears in your matches. Change them any time in Matching settings.'),
  ('en', 'onboardingBeatNearby1', 'The nearby map shows how many people are around you… Each circle is a small group of members close to your location.'),
  ('en', 'onboardingBeatNearby2', 'Tap the radius pill at the top to change how far to search, and simply move the map to explore a different area.'),
  ('en', 'onboardingBeatNearby3', 'Nobody sees your exact location… Others only see an approximate distance, and only when you are visible.'),
  ('en', 'onboardingBeatNearby4', 'Matching is proximity based… The app compares people who are near each other AND share an intent or interest. The wider your radius, the more people you can discover.'),
  ('en', 'onboardingBeatNearby5', 'Your distance preference sets the search range for matches… A larger radius finds more people but may be less relevant. A smaller radius keeps matches close and specific.'),
  ('en', 'onboardingBeatMatches1', 'Every time you and another member want the same kind of connection, they appear here as a match… with a score showing how well you fit.'),
  ('en', 'onboardingBeatMatches2', 'Matches last 24 hours by default… The countdown on each card shows how long you have to say hello. Either of you can extend a match once for extra time… and once you start chatting, the match never expires.'),
  ('en', 'onboardingBeatMatches3', 'Sort or filter your matches, and tap a card to view the full profile before starting a chat.'),
  ('en', 'onboardingBeatMatches4', 'Use these intent filters to narrow matches to friends, dating, or both. The filter chips mirror your own intent selections from your profile.'),
  ('en', 'onboardingBeatMatches5', 'A match is created when two members share an intent and both are visible and nearby… Shared interests, mutual preferences, and proximity all contribute to the match score you see on each card.'),
  ('en', 'onboardingBeatChats1', 'All your conversations live here… Unread chats are highlighted, and you can filter them by intent.'),
  ('en', 'onboardingBeatChats2', 'Messages are end to end encrypted, so your conversations stay private… They can even be translated automatically, so language is never a barrier.'),
  ('en', 'onboardingBeatChats3', 'Filter chats by intent to focus on friends, dating, or both. The same filters you set in your profile apply here.'),
  ('en', 'onboardingBeatChats4', 'Stay safe while chatting… You can block or report anyone from the chat menu, and share your live location with one match at a time, only for as long as you choose.'),
  ('en', 'onboardingBeatEvents1', 'Events let you meet people in person… Join something nearby, or tap the plus button to create your own event for members who share your interests. You can even import an event from a link, a ticket photo, or your calendar.'),
  ('en', 'onboardingBeatEvents2', 'Bring your plans with you… Import events from your Google, Outlook, Apple or device calendar into MatchMe, then meet members who are going too.'),
  ('en', 'onboardingBeatEvents3', 'See who is going, RSVP, and chat with members before the event starts… Event details stay in the card right above.'),
  ('en', 'onboardingBeatProfile1', 'This is how others see you… Your photos, age, bio and interests. A complete profile gets far more attention.'),
  ('en', 'onboardingBeatProfile2', 'Verify your profile with a short live selfie check… The verified badge builds trust, brings you more matches, and can unlock features available only to verified members.'),
  ('en', 'onboardingBeatProfile3', 'Your gender, age range, and preferences determine who can match with you… These are fully adjustable in Match Preferences under Matching settings.'),
  ('en', 'onboardingBeatProfile4', 'Tap edit any time to update your photos or details through the same wizard you already know.'),
  ('en', 'onboardingBeatSettings1', 'Open settings with the gear icon at the top of the screen.'),
  ('en', 'onboardingBeatSettings2', 'Under Matching, you control the search distance, background matching, and retro matching. Tap to see all matching controls in one place.'),
  ('en', 'onboardingBeatSettings3', 'Under Match Preferences, you set the age range, gender preference, height range, and lifestyle or family filters you are looking for… These directly determine who can match with you.'),
  ('en', 'onboardingBeatSettings4', 'Under Invisibility Rules, you choose when you are automatically invisible… at work, at home, or on a schedule. You stay in control of who can see you and match with you.'),
  ('en', 'onboardingBeatSettings5', 'Three matching modes shape your experience… Shared Event Matching finds people at the same event, Retro Matching finds people you crossed paths with offline, and Background Matching keeps searching while you are away. All three live in the Matching section above.'),
  ('en', 'onboardingBeatFinish1', 'That is the end of the tour… Everything is ready for you. MatchMe is now quietly finding compatible people near you based on your preferences. Invite friends with your referral link to earn rewards for you both… Explore at your own pace, and replay this tour any time from the settings screen.'),
  ('en', 'onboardingDemoGreeting', 'Hi there, Alex!'),
  ('en', 'onboardingDemoIntentFriends', 'Friends'),
  ('en', 'onboardingDemoIntentDating', 'Dating'),
  ('en', 'onboardingDemoRadius', '2 km'),
  ('en', 'onboardingDemoDaySat', 'SAT'),
  ('en', 'onboardingDemoDaySun', 'SUN'),
  ('en', 'onboardingDemoTimeLeft', '23h'),
  ('en', 'demoName1', 'Maya, 28'),
  ('en', 'demoName2', 'Daniel, 31'),
  ('en', 'demoName3', 'Sofia, 26'),
  ('en', 'demoAge1', '28'),
  ('en', 'demoGender1', 'Woman'),
  ('en', 'demoBio', 'Hiking, live music and good coffee.'),
  ('en', 'demoInterest1', 'Hiking'),
  ('en', 'demoInterest2', 'Live music'),
  ('en', 'demoInterest3', 'Travel'),
  ('en', 'demoChatMessage1', 'Hi Maya! Loved your hiking photos.'),
  ('en', 'demoChatMessage2', 'Thank you! Are you free this weekend?'),
  ('en', 'demoChatMessage3', 'Definitely… coffee on Saturday?'),
  ('en', 'demoLastMessage1', 'Sounds like a plan!'),
  ('en', 'onboardingDemoMessageHint', 'Write a message…'),
  ('en', 'onboardingDemoJoin', 'Join'),
  ('en', 'demoEventTitle', 'Sunset beach volleyball'),
  ('en', 'demoEventMeta', 'Central Beach · Saturday 17:00'),
  ('en', 'onboardingBeatProfileVerifyLabel', 'Verification in progress…'),
  ('en', 'onboardingBeatProfileVerifyHint', 'A live selfie check is needed to unlock the verified badge.')
INSERT INTO public.translations (locale, key, value) VALUES
  ('es', 'onboardingChapterWelcome', 'Bienvenido a MatchMe'),
  ('es', 'onboardingChapterHome', 'Tu pantalla de inicio'),
  ('es', 'onboardingChapterNearby', 'Descubre personas cerca'),
  ('es', 'onboardingChapterMatches', 'Tus coincidencias'),
  ('es', 'onboardingChapterChats', 'Chatea con seguridad'),
  ('es', 'onboardingChapterEvents', 'Únete a eventos'),
  ('es', 'onboardingChapterProfile', 'Tu perfil'),
  ('es', 'onboardingChapterSettings', 'Personalízalo todo'),
  ('es', 'onboardingChapterFinish', '¡Todo listo!'),
  ('es', 'onboardingBeatWelcome1', 'Bienvenido a MatchMe… Este breve recorrido te muestra lo que puede hacer la app y cómo usarla. Toca Siguiente para avanzar, o Saltar para salir del recorrido en cualquier momento.'),
  ('es', 'onboardingBeatWelcome2', 'Así funciona… Creas tu perfil, descubres personas cerca de ti que buscan lo mismo que tú, y chatean con seguridad cuando ambos se conectan. Verificar tu perfil con una selfie en vivo te da una insignia de confianza.'),
  ('es', 'onboardingBeatHome1', 'Esta es tu pantalla de inicio, tu panel diario… Todo en MatchMe está a un solo toque desde aquí.'),
  ('es', 'onboardingBeatHome2', 'Las tarjetas de arriba muestran cuántas personas están cerca en este momento, quién está en línea y tu nivel de suscripción. Toca una tarjeta para abrirla.'),
  ('es', 'onboardingBeatHome3', 'Abajo te esperan tus coincidencias y chats más recientes, para que continúes donde lo dejaste.'),
  ('es', 'onboardingBeatHome4', 'Usa estos filtros para concentrarte en lo que buscas… amistad, citas o cualquier otra intención que hayas elegido en tu perfil.'),
  ('es', 'onboardingBeatHome5', 'En segundo plano, MatchMe compara continuamente tus preferencias con otros miembros cercanos… La compatibilidad en segundo plano sigue buscando incluso cuando no estás usando la app activamente, así que aparecen nuevas coincidencias en tiempo real.'),
  ('es', 'onboardingBeatHome6', 'Lo que crea una coincidencia depende de tu configuración… Tu distancia de búsqueda, rango de edad, preferencias de género, intereses compartidos y filtros de estilo de vida determinan quién aparece en tus coincidencias. Cámbialos en cualquier momento en Personalización.'),
  ('es', 'onboardingBeatNearby1', 'El mapa de cercanía muestra cuántas personas hay alrededor tuyo… Cada círculo es un pequeño grupo de miembros cerca de tu ubicación.'),
  ('es', 'onboardingBeatNearby2', 'Toca la píldora de radio arriba para cambiar la distancia de búsqueda, y simplemente mueve el mapa para explorar otra zona.'),
  ('es', 'onboardingBeatNearby3', 'Nadie ve tu ubicación exacta… Los demás solo ven una distancia aproximada, y solo cuando eres visible.'),
  ('es', 'onboardingBeatNearby4', 'La compatibilidad se basa en la proximidad… La app compara personas que están cerca Y comparten una intención o interés. Cuanto mayor sea tu radio, más personas puedes descubrir.'),
  ('es', 'onboardingBeatNearby5', 'Tu preferencia de distancia establece el rango de búsqueda para coincidencias… Un radio mayor encuentra a más personas pero puede ser menos relevante. Un radio menor mantiene las coincidencias cercanas y específicas.'),
  ('es', 'onboardingBeatMatches1', 'Cada vez que tú y otra persona buscan el mismo tipo de conexión, aparece aquí como una coincidencia… con una puntuación que muestra qué tan compatibles son.'),
  ('es', 'onboardingBeatMatches2', 'Las coincidencias duran 24 horas por defecto… La cuenta regresiva en cada tarjeta muestra cuánto tiempo tienes para saludar. Cualquiera de los dos puede extender una coincidencia una vez para ganar más tiempo… y una vez que empiezas a chatear, la coincidencia nunca caduca.'),
  ('es', 'onboardingBeatMatches3', 'Ordena o filtra tus coincidencias, y toca una tarjeta para ver el perfil completo antes de empezar un chat.'),
  ('es', 'onboardingBeatMatches4', 'Usa estos filtros de intención para reducir las coincidencias a amistad, citas, o ambas. Los chips de filtro reflejan tus propias selecciones de intención de tu perfil.'),
  ('es', 'onboardingBeatMatches5', 'Se crea una coincidencia cuando dos miembros comparten una intención y ambos son visibles y están cerca… Los intereses compartidos, las preferencias mutuas y la proximidad contribuyen a la puntuación de coincidencia que ves en cada tarjeta.'),
  ('es', 'onboardingBeatChats1', 'Todas tus conversaciones viven aquí… Los chats no leídos se destacan, y puedes filtrarlos por intención.'),
  ('es', 'onboardingBeatChats2', 'Los mensajes están cifrados de extremo a extremo, así que tus conversaciones son privadas… Incluso pueden traducirse automáticamente, para que el idioma nunca sea una barrera.'),
  ('es', 'onboardingBeatChats3', 'Filtra los chats por intención para concentrarte en amistad, citas, o ambas. Los mismos filtros que configuraste en tu perfil se aplican aquí.'),
  ('es', 'onboardingBeatChats4', 'Mantente seguro mientras chateas… Puedes bloquear o denunciar a cualquier persona desde el menú del chat, y compartir tu ubicación en vivo con un chat a la vez, solo por el tiempo que elijas.'),
  ('es', 'onboardingBeatEvents1', 'Los eventos te permiten conocer personas en persona… Únete a algo cerca, o crea tu propio evento para miembros que comparten tus intereses. Incluso puedes importar un evento desde un enlace, una foto de boleto o tu calendario.'),
  ('es', 'onboardingBeatEvents2', 'Lleva tus planes contigo… Importa eventos de tu Google, Outlook, Apple o calendario de tu dispositivo a MatchMe, luego conoce a los miembros que también van.'),
  ('es', 'onboardingBeatEvents3', 'Ve quién va, confirma asistencia y chatea con los miembros antes de que empiece el evento… Los detalles del evento se mantienen en la tarjeta justo arriba.'),
  ('es', 'onboardingBeatProfile1', 'Así te ven los demás… Tus fotos, edad, biografía e intereses. Un perfil completo atrae mucha más atención.'),
  ('es', 'onboardingBeatProfile2', 'Verifica tu perfil con una breve selfie en vivo… La insignia de verificación genera confianza y te trae más coincidencias, y puede desbloquear características disponibles solo para miembros verificados.'),
  ('es', 'onboardingBeatProfile3', 'Tu género, rango de edad y preferencias determinan con quién puedes coincidir… Estos se ajustan completamente en Preferencias de coincidencia en Personalización.'),
  ('es', 'onboardingBeatProfile4', 'Toca editar en cualquier momento para actualizar tus fotos o datos en el mismo asistente que ya conoces.'),
  ('es', 'onboardingBeatSettings1', 'Abre la configuración con el ícono de engranaje en la parte superior de la pantalla.'),
  ('es', 'onboardingBeatSettings2', 'En Coincidencias, controlas la distancia de búsqueda, la compatibilidad en segundo plano y la compatibilidad retro. Toca para ver todos los controles de coincidencia en un lugar.'),
  ('es', 'onboardingBeatSettings3', 'En Preferencias de coincidencia, configuras el rango de edad, la preferencia de género, el rango de altura y los filtros de estilo de vida o familia que buscas… Estos determinan directamente con quién puedes coincidir.'),
  ('es', 'onboardingBeatSettings4', 'En Reglas de invisibilidad, eliges cuándo estás automáticamente invisible… en el trabajo, en casa o en un horario. Tienes el control de quién puede verte y coincidir contigo.'),
  ('es', 'onboardingBeatSettings5', 'Tres modos de compatibilidad dan forma a tu experiencia… La compatibilidad por evento compartido encuentra personas en el mismo evento, la compatibilidad retro encuentra personas que cruzaste caminar fuera de línea, y la compatibilidad en segundo plano sigue buscando mientras estás ausente. Los tres viven en la sección Coincidencias arriba.'),
  ('es', 'onboardingBeatFinish1', 'Ese es el final del recorrido… Todo está listo para ti. MatchMe ahora está buscando discretamente personas compatibles cerca de ti según tus preferencias. Invita amigos con tu enlace de referidos para ganar recompensas para ambos… Explora a tu ritmo, y repite este recorrido cuando quieras desde la pantalla de configuración.'),
  ('es', 'onboardingDemoGreeting', '¡Hola, Alex!'),
  ('es', 'onboardingDemoIntentFriends', 'Amistad'),
  ('es', 'onboardingDemoIntentDating', 'Citas'),
  ('es', 'onboardingDemoRadius', '2 km'),
  ('es', 'onboardingDemoDaySat', 'SÁB'),
  ('es', 'onboardingDemoDaySun', 'DOM'),
  ('es', 'onboardingDemoTimeLeft', '23 h'),
  ('es', 'demoName1', 'Maya, 28'),
  ('es', 'demoName2', 'Daniel, 31'),
  ('es', 'demoName3', 'Sofía, 26'),
  ('es', 'demoAge1', '28'),
  ('es', 'demoGender1', 'Mujer'),
  ('es', 'demoBio', 'Senderismo, música en vivo y buen café.'),
  ('es', 'demoInterest1', 'Senderismo'),
  ('es', 'demoInterest2', 'Música en vivo'),
  ('es', 'demoInterest3', 'Viajar'),
  ('es', 'demoChatMessage1', '¡Hola Maya! Me encantaron tus fotos de senderismo.'),
  ('es', 'demoChatMessage2', '¡Gracias! ¿Estás libre este fin de semana?'),
  ('es', 'demoChatMessage3', 'Seguro… ¿un café el sábado?'),
  ('es', 'demoLastMessage1', '¡Parece un plan!'),
  ('es', 'onboardingDemoMessageHint', 'Escribe un mensaje…'),
  ('es', 'onboardingDemoJoin', 'Unirse'),
  ('es', 'demoEventTitle', 'Vóleibol playero al atardecer'),
  ('es', 'demoEventMeta', 'Playa Central · sábado 17:00'),
  ('es', 'onboardingBeatProfileVerifyLabel', 'Verificación en progreso…'),
  ('es', 'onboardingBeatProfileVerifyHint', 'Se necesita una selfie en vivo para desbloquear la insignia de verificación.')
INSERT INTO public.translations (locale, key, value) VALUES
  ('he', 'onboardingChapterWelcome', 'ברוכים הבאים ל-MatchMe'),
  ('he', 'onboardingChapterHome', 'מסך הבית שלכם'),
  ('he', 'onboardingChapterNearby', 'מגלים אנשים בסביבה'),
  ('he', 'onboardingChapterMatches', 'ההתאמות שלכם'),
  ('he', 'onboardingChapterChats', 'שיחות בטוחות'),
  ('he', 'onboardingChapterEvents', 'הצטרפו לאירועים'),
  ('he', 'onboardingChapterProfile', 'הפרופיל שלכם'),
  ('he', 'onboardingChapterSettings', 'התאמו אישית'),
  ('he', 'onboardingChapterFinish', 'הכול מוכן!'),
  ('he', 'onboardingBeatWelcome1', 'ברוכים הבאים ל-MatchMe… הסיור הקצר הזה מסביר מה האפליקציה יודעת לעשות ואיך משתמשים בה. הקישו על הבא כדי להתקדם, או על דלג כדי לצאת מהסיור בכל רגע.'),
  ('he', 'onboardingBeatWelcome2', 'כך זה עובד… אתם בונים פרופיל, מגלים אנשים בסביבתכם שמחפשים את אותו דבר כמוכם, ומנהלים שיחות בטוחות כשאתם מתחברים. אימות הפרופיל בסלפי חיה מקנה תג אמון.'),
  ('he', 'onboardingBeatHome1', 'זה מסך הבית שלכם, לוח הבקרה היודי… הכול ב-MatchMe נגיש מכאן בנגיעה אחת.'),
  ('he', 'onboardingBeatHome2', 'הכרטיסים למעלה מראים כמה אנשים נמצאים סביבכם עכשיו, מי מחובר, ואת מסלול המנוי שלכם. הקישו על כרטיס כדי לפתוח אותו.'),
  ('he', 'onboardingBeatHome3', 'למטה ממתינות ההתאמות והשיחות האחרונות שלכם, כדי שתוכלו להמשיך בדיוק מהמקום שבו הפסקתם.'),
  ('he', 'onboardingBeatHome4', 'השתמשו במסננים כדי להתמקד במה שבא לכם… חברות, דייטים או כל מטרה אחרת שבחרתם בפרופיל.'),
  ('he', 'onboardingBeatHome5', 'מאחורי הקלעים, MatchMe משווה ברציפות את ההעדפות שלכם עם חברים אחרים בסביבה… התאמה ברקע ממשיכה לחפש גם כשאתם לא משתמשים באפליקציה באופן פעיל, כך שהתאמות חדשות מופיעות בזמן אמת.'),
  ('he', 'onboardingBeatHome6', 'מה שיוצר התאמה תלוי בהגדרות שלכם… טווח החיפוש, טווח הגילאים, העדפת המגדר, האינטרסים המשותפים ופילטרי האורח חיים שלכם קובעים מי מופיע בהתאמות שלכם. שנו אותם בכל עת בהתאמה אישית.'),
  ('he', 'onboardingBeatNearby1', 'מפת הסביבה מראה כמה אנשים נמצאים סביבכם… כל עיגול הוא קבוצה קטנה של חברים קרובים למיקום שלכם.'),
  ('he', 'onboardingBeatNearby2', 'הקישו על בועת הרדיוס למעלה כדי לשנות את טווח החיפוש, ופשוט הזיזו את המפה כדי לחקור אזור אחר.'),
  ('he', 'onboardingBeatNearby3', 'אף אחד לא רואה את המיקום המדויק שלכם… האחרים רואים רק מרחק משוער, ורק כשאתם גלויים.'),
  ('he', 'onboardingBeatNearby4', 'ההתאמות מבוססות על קרבה… האפליקציה משווה אנשים שהם קרובים זה לזה וגם חולקים כוונה או עניין. ככל שהרדיוס שלכם גדול יותר, כך אתם יכולים לגלות יותר אנשים.'),
  ('he', 'onboardingBeatNearby5', 'ההעדפה שלכם למרחק מגדירה את טווח החיפוש להתאמות… רדיוס גדול יותר מוצא יותר אנשים אך יהיה פחות רלוונטי. רדיוס קטן יותר שומר על התאמות קרובות וספציפיות.'),
  ('he', 'onboardingBeatMatches1', 'בכל פעם שאתם ומישהו נוסף מחפשים את אותו סוג קשר, הוא מופיע כאן כהתאמה… עם ציון שמראה עד כמה אתם מתאימים.'),
  ('he', 'onboardingBeatMatches2', 'ההתאמות פגות לאחר מספר ימים… הספירה לאחור בכל כרטיס מראה כמה זמן נותר לשלוח ברכה. אחד מכם יכול להאריך התאמה פעם אחת לזמן נוסף… וברגע שמתחילים לדבר, ההתאמה לא מוגבלת.'),
  ('he', 'onboardingBeatMatches3', 'מיון או סינון של ההתאמות שלכם, והקישו על כרטיס כדי לצפות בפרופיל המלא לפני התחלת שיחה.'),
  ('he', 'onboardingBeatMatches4', 'השתמשו בפילטרי הכוונה האלה כדי לצמצם התאמות לחברות, דייטים, או שניהם.Chipי הפילטר משקפים את בחירות הכוונה שלכם מהפרופיל שלכם.'),
  ('he', 'onboardingBeatMatches5', 'התאמה נוצרת כששני חברים חולקים כוונה ושניהם גלויים וקרובים… אינטרסים משותפים, העדפות הדדיות וקרבה תורמים כולם לציון ההתאמה שאתם רואים בכל כרטיס.'),
  ('he', 'onboardingBeatChats1', 'כל השיחות שלכם נמצאות כאן… שיחות שלא נקראו מסומנות, ואפשר לסנן אותן לפי מטרה.'),
  ('he', 'onboardingBeatChats2', 'ההודעות מוצפנות מקצה לקצה, כך שהשיחות שלכם נשארות פרטיות… גם אפשר לתרגם אותן אוטומטית, כדי ששפה לא תהיה מחסום.'),
  ('he', 'onboardingBeatChats3', 'סננו שיחות לפי מטרה כדי להתמקד בחברות, דייטים, או שניהם. אתם אותם הסננים שהגדרתם בפרופיל שלכם חלים כאן.'),
  ('he', 'onboardingBeatChats4', 'היטברו בזמן הצאט… אתם יכולים לחסום או לדווח על מישהו מתפריח הצאט, ולשתף את המיקום החי שלכם עם אחד לכל היותר, רק לכמה שאתם בוחרים.'),
  ('he', 'onboardingBeatEvents1', 'אירועים מאפשרים להיפגש פנים אל פנים… הצטרפו למשהו בסביבה, או צרו אירוע משלכם לחברים שחולקים את תחומי העניין שלכם. אתם אפילו יכולים לייבא אירוע מקישור, תמונת כרטיס או הלוח שלכם.'),
  ('he', 'onboardingBeatEvents2', 'קחו את התוכניות שלכם איתך… ייבאו אירועים מ-Google שלכם, Outlook, Apple או לוח המסך של המכשיר ל-MatchMe, ותפגושו חברים הולכים שם.'),
  ('he', 'onboardingBeatEvents3', 'ראו מי הולך, אישרו נוכחות ודברו עם חברים לפני שהאירוע מתחיל… פרטי האירוע נשארים בכרטיס ממש למעלה.'),
  ('he', 'onboardingBeatProfile1', 'כך אחרים רואים אתכם… התמונות, הגיל, הביוגרפיה ותחומי העניין שלכם. פרופיל מלא מקבל הרבה יותר תשומת לב.'),
  ('he', 'onboardingBeatProfile2', 'אמתו את הפרופיל בבדיקת סלפי חיה קצרה… תג האימות מייצר אמון ומביא לכם יותר התאמות, ויכול לפתוח תכונות זמינות רק לחברים מאומתים.'),
  ('he', 'onboardingBeatProfile3', 'המגדר, טווח הגילאים וההעדפות שלכם קובעים עם מי אתם יכולים להתאים… אלה ניתנים לשינוי מלא בהעדפות ההתאמה תחת התאמה אישית.'),
  ('he', 'onboardingBeatProfile4', 'הקישו על עריכה בכל עת כדי לעדכן תמונות או פרטים דרך אותו אשף שכבר מכירים.'),
  ('he', 'onboardingBeatSettings1', 'פתחו את ההגדרות באמצעות סמל המפתח למעלה במסך.'),
  ('he', 'onboardingBeatSettings2', 'תחת ההתאמות, אתם שולטים בטווח החיפוש, ההתאמה ברקע וההתאמה הרטרו. הקישו כדי לראות את כל בקרות ההתאמה במקום אחד.'),
  ('he', 'onboardingBeatSettings3', 'תחת העדפות ההתאמה, אתם מגדירים את טווח הגילאים, העדפת המגדר, טווח הגובה ופילטרי אורח החיים או המשפחה שאתם מחפשים… אלה קובעים ישיר עם מי אתם יכולים להתאים.'),
  ('he', 'onboardingBeatSettings4', 'תחת כללי הבלתי נראות, אתם בוחרים מתי אתם אוטומטית בלתי נראים… בעבודה, בבית, או לוח זמנים. אתם תמיד שולטים במי יכול לראות אתכם ולהתאים לכם.'),
  ('he', 'onboardingBeatSettings5', 'שלושה מצבי התאמה מעצבים את הניסיון שלכם… התאמה באירוע משותף מוצאת אנשים באותו אירוע, התאמה רטרו מוצאת אנשים שחלפתם בהם מולרח החוץ, והתאמה ברקע ממשיכה לחפש בזמן שאתם לא נמצאים. שלושתם חיים בסקטור ההתאמות למעלה.'),
  ('he', 'onboardingBeatFinish1', 'זהו סוף הסיור… הכול מוכן בשבילכם. MatchMe עכשיו מחפש בשקט אנשים תואמים קרובים לכם לפי ההעדפות שלכם. הזמינו חברים עם קישור ההפניה שלכם כדי לזכות בתגמולים לשניכם… חקרו בקצב שלכם, וחזרו על הסיור הזה בכל עת ממסך ההגדרות.'),
