-- Full onboarding narrative sync.
-- Brings all onboarding beat/demo narration keys in public.translations
-- up to date with the built-in fallbacks in locale_provider.dart for
-- en/es/he. Covers every beat in the current chapter structure
-- (35 beats across 9 chapters).
-- Idempotent: safe to re-run (ON CONFLICT DO UPDATE).
-- Table: public.translations(locale, key, value)

-- English translations (from locale_provider.dart _defaultTranslations)
ON CONFLICT (locale, key) DO UPDATE SET value = EXCLUDED.value;

-- Spanish translations
ON CONFLICT (locale, key) DO UPDATE SET value = EXCLUDED.value;

-- Hebrew translations
ON CONFLICT (locale, key) DO UPDATE SET value = EXCLUDED.value;
